35	     * registration date: {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and
36	     * {@code SENIOR} at 65 or older. Returns {@code null} when the birth date or registration
37	     * date is absent, so an owner created without a birth date carries no age band.
38	     */
39	    default org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum ageBand(Owner owner) {
40	        java.time.LocalDate birthDate = owner.getBirthDate();
41	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
42	        if (birthDate == null || registrationDate == null) {
43	            return null;
44	        }
45	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
46	        if (age < 18) {
47	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.MINOR;
48	        }
49	        if (age < 65) {
50	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.ADULT;
51	        }
52	        return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.SENIOR;
53	    }
54	
55	    /**
56	     * Computes the owner's check digit: a single Luhn check digit (0-9) over the digits contained
57	     * in the owner's customer code. Returns {@code null} when the customer code is absent.
58	     */
59	    default Integer checkDigit(Owner owner) {
60	        String customerCode = owner.getCustomerCode();
61	        if (customerCode == null) {
62	            return null;
63	        }
64	        int sum = 0;
65	        boolean dbl = true;
66	        for (int i = customerCode.length() - 1; i >= 0; i--) {
67	            char c = customerCode.charAt(i);
68	            if (c < '0' || c > '9') {
69	                continue;
